<template><div class="finance-modal" @click.self="$emit('close')"><section role="dialog" aria-modal="true" :aria-label="`Add ${label(kind)}`" class="finance-dialog"><header><h2>{{ kind==='expenses'?'New expense request':`Add ${label(kind)}` }}</h2><button type="button" @click="$emit('close')" aria-label="Close form">×</button></header><p v-if="error" role="alert">{{ error }}</p><form @submit.prevent="save"><div class="form-grid"><label v-for="f in fields" :key="f.key">{{ f.label }}<select v-if="f.type==='select'" v-model="draft[f.key]" :required="!optional(f)"><option value="">Select…</option><option v-for="item in options(f)" :key="item.value" :value="item.value">{{ item.label }}</option></select><textarea v-else-if="f.type==='textarea'" v-model="draft[f.key]" :required="!f.optional" rows="3" maxlength="5000"/><input v-else v-model="draft[f.key]" :type="f.type" :required="!f.optional" :min="f.min" :step="f.step" :maxlength="f.type==='text'?200:undefined" /></label></div><p v-if="kind==='receipts'" class="finance-callout">Record money actually received. Grant awards alone are not received funds.</p><p v-if="kind==='expenses'" class="finance-callout">Saved as a draft. Attach evidence, then submit it for finance review.</p><footer><button type="button" @click="$emit('close')">Cancel</button><button class="primary" :disabled="busy">{{ busy?'Saving…':'Save' }}</button></footer></form></section></div></template>
<script setup>
import {ref,computed,onBeforeUnmount} from 'vue';import api from '../../services/api';import {forms,dollarCents,label} from './financeForms';
const props=defineProps({agencyId:Number,kind:String,data:Object});const emit=defineEmits(['close','saved']);const fields=computed(()=>forms[props.kind]||[]),draft=ref(Object.fromEntries((forms[props.kind]||[]).map(f=>[f.key,f.type==='date'?new Date().toISOString().slice(0,10):'']))),busy=ref(false),error=ref('');let active=true;const requestKey=crypto.randomUUID();onBeforeUnmount(()=>{active=false;});
const optional=f=>f.optional||['grantId','partnerId','eventId'].includes(f.key)||(props.kind==='requests'&&['programId','grantId'].includes(f.key));
function options(f){if(Array.isArray(f.source))return f.source.map(v=>({value:v,label:label(v)}));return (props.data[f.source]||[]).filter(x=>f.source!=='events'||!draft.value.programId||x.program_id===Number(draft.value.programId)).map(x=>({value:x.id,label:x.name}));}
async function save(){busy.value=true;error.value='';try{const body={...draft.value};if(body.amount)body.amountCents=dollarCents(body.amount);delete body.amount;for(const key of Object.keys(body))if(key.endsWith('Id'))body[key]=body[key]?Number(body[key]):null;const path=props.kind==='expenses'?'expenses':`records/${props.kind}`;if(props.kind==='expenses')body.requestKey=requestKey;await api.post(`/finance-operations/${props.agencyId}/${path}`,body);if(active)emit('saved');}catch(e){if(active)error.value=e.response?.data?.error?.message||e.message||'Could not save';}finally{if(active)busy.value=false;}}
</script>
